import jss from "jss";
import preset from "jss-preset-default";
import { createTheme } from "../theming";
import { generateStylesheet } from "./generateStylesheet";

const theme = createTheme("airbus");
jss.setup({
  ...preset(),
});

describe("generateStylesheet", () => {
  it("should transform camelCased properties", () => {
    const css = generateStylesheet(
      "button",
      () => ({
        root: {
          backgroundColor: "white",
        },
      }),
      theme,
      jss
    );
    expect(css).toMatchInlineSnapshot(`
      ".ds-button {
        all: initial;
        box-sizing: border-box;
        font-family: Inter, Arial, sans-serif;
        background-color: white;
      }"
    `);
  });

  it("should handle pseudo-selectors", () => {
    const css = generateStylesheet(
      "button",
      () => ({
        root: {
          color: "white",
          "&:hover": {
            color: "red",
          },
        },
      }),
      theme,
      jss
    );
    expect(css).toMatchInlineSnapshot(`
      ".ds-button {
        all: initial;
        color: white;
        box-sizing: border-box;
        font-family: Inter, Arial, sans-serif;
      }
      .ds-button:hover {
        color: red;
      }"
    `);
  });

  it("should handle variants", () => {
    const css = generateStylesheet(
      "button",
      () => {
        return {
          root: {
            margin: 0,
          },
          _primary: {
            color: "red",
          },
          _secondary: {
            color: "gray",
          },
        };
      },
      theme,
      jss
    );
    expect(css).toMatchInlineSnapshot(`
      ".ds-button {
        all: initial;
        margin: 0;
        box-sizing: border-box;
        font-family: Inter, Arial, sans-serif;
      }
      .ds-button--primary {
        color: red;
      }
      .ds-button--secondary {
        color: gray;
      }"
    `);
  });

  it("should handle dependent variants", () => {
    const css = generateStylesheet(
      "button",
      () => {
        return {
          root: {
            margin: 0,
            color: "transparent",
          },
          _primary: {
            color: "red",
          },
          _dark: {
            "&$_primary": {
              color: "white",
            },
          },
        };
      },
      theme,
      jss
    );
    expect(css).toMatchInlineSnapshot(`
      ".ds-button {
        all: initial;
        color: transparent;
        margin: 0;
        box-sizing: border-box;
        font-family: Inter, Arial, sans-serif;
      }
      .ds-button--primary {
        color: red;
      }
      .ds-button--dark.ds-button--primary {
        color: white;
      }"
    `);
  });
});
